public static boolean validParentheses(String input) {
    Deque<Character> stack = new ArrayDeque<>();
    Map<Character, Character> pairs = Map.of(')', '(', '}', '{', ']', '[');
    for (char c : input.toCharArray()) {
        if (c == '(' || c == '[' || c == '{') stack.push(c);
        else if (stack.isEmpty() || stack.pop() != pairs.get(c)) return false;
    }
    return stack.isEmpty();

}

public static boolean validParentheses(String input) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : input.toCharArray()) {
        if (c == '(' || c == '[' || c == '{') stack.push(c);
        else if (c == ')' && (stack.isEmpty() || stack.pop() != '(')) return false;
        else if (c == ']' && (stack.isEmpty() || stack.pop() != '[')) return false;
        else if (c == '}' && (stack.isEmpty() || stack.pop() != '{')) return false;
    }
    return stack.isEmpty();

}

public static boolean validParentheses(String input) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : input.toCharArray()) {
        switch (c) {
            case '(':
            case '[':
            case '{':
                stack.push(c);
                break;
            case ')':
                if (stack.isEmpty() || stack.pop() != '(') return false;
                break;
            case ']':
                if (stack.isEmpty() || stack.pop() != '[') return false;
                break;
            case '}':
                if (stack.isEmpty() || stack.pop() != '{') return false;
                break;
            default:
                break;
        }
    }
    return stack.isEmpty();

}

public static boolean validParentheses(String input) {
    Deque<Character> stack = new ArrayDeque<>();
    return input.chars().allMatch(ch -> {
        if (ch == '(' || ch == '[' || ch == '{') {
            stack.push((char) ch);
            return true;
        }
        if (ch == ')' && (stack.isEmpty() || stack.pop() != '(')) return false;
        if (ch == ']' && (stack.isEmpty() || stack.pop() != '[')) return false;
        if (ch == '}' && (stack.isEmpty() || stack.pop() != '{')) return false;
        return true;
    }) && stack.isEmpty();

}
